const fs = require("fs");
const path = require("path");

const ROOT =
  process.cwd();

const BACKUP_DIR =
  path.join(
    ROOT,
    "scripts",
    "backups",
  );

const PAYLOADS =
  {"lib/research/get-forward-oos-observability-dashboard-v1.ts": "", "app/api/forward-oos/observability/route.ts": "", "app/forward-oos/page.tsx": "", "scripts/forward-oos-observability-dashboard-v1-contract-test.ts": "", "scripts/forward-oos-observability-dashboard-v1-static-verify.cjs": ""};

function fail(
  reason,
  extra = {},
) {
  console.error(
    JSON.stringify(
      {
        status:
          "AI_STOCK_LAB_FORWARD_OOS_OBSERVABILITY_DASHBOARD_V1_INSTALL_FAILED",

        reason,
        ...extra,
      },
      null,
      2,
    ),
  );

  process.exitCode = 1;
}

function writePayload(
  rel,
  payload,
) {
  const target =
    path.join(
      ROOT,
      rel,
    );

  fs.mkdirSync(
    path.dirname(
      target,
    ),
    {
      recursive:
        true,
    },
  );

  fs.writeFileSync(
    target,
    Buffer.from(
      payload,
      "base64",
    ).toString(
      "utf8",
    ),
    "utf8",
  );
}

const home =
  path.join(
    ROOT,
    "app",
    "page.tsx",
  );

const packageFile =
  path.join(
    ROOT,
    "package.json",
  );

if (
  !fs.existsSync(
    home,
  ) ||
  !fs.existsSync(
    packageFile,
  )
) {
  fail(
    "APP_PAGE_OR_PACKAGE_NOT_FOUND",
  );
} else {
  fs.mkdirSync(
    BACKUP_DIR,
    {
      recursive:
        true,
    },
  );

  const homeBackup =
    path.join(
      BACKUP_DIR,
      "app-page.before-forward-oos-dashboard-v1.tsx",
    );

  if (
    !fs.existsSync(
      homeBackup,
    )
  ) {
    fs.copyFileSync(
      home,
      homeBackup,
    );
  }

  for (
    const [
      rel,
      payload,
    ] of Object.entries(
      PAYLOADS,
    )
  ) {
    writePayload(
      rel,
      payload,
    );
  }

  let homeSource =
    fs.readFileSync(
      home,
      "utf8",
    );

  const navMarker =
    "AI_STOCK_LAB_FORWARD_OOS_DASHBOARD_NAV_V1";

  if (
    !homeSource.includes(
      navMarker,
    )
  ) {
    const closeNav =
      homeSource.indexOf(
        "</nav>",
      );

    if (
      closeNav < 0
    ) {
      fail(
        "SIDEBAR_NAV_CLOSE_TAG_NOT_FOUND",
      );
      return;
    }

    const insertion =
      [
        "          {/* AI_STOCK_LAB_FORWARD_OOS_DASHBOARD_NAV_V1 */}",
        '          <a href="/forward-oos">Forward OOS</a>',
        "",
      ].join(
        "\n",
      );

    homeSource =
      homeSource.slice(
        0,
        closeNav,
      ) +
      insertion +
      homeSource.slice(
        closeNav,
      );

    fs.writeFileSync(
      home,
      homeSource,
      "utf8",
    );
  }

  let pkg;

  try {
    pkg =
      JSON.parse(
        fs.readFileSync(
          packageFile,
          "utf8",
        ),
      );
  } catch (
    error
  ) {
    fail(
      "PACKAGE_JSON_PARSE_FAILED",
      {
        error:
          String(
            error instanceof Error
              ? error.message
              : error,
          ),
      },
    );

    return;
  }

  pkg.scripts ||= {};

  pkg.scripts[
    "test:forward-oos-observability-dashboard-static"
  ] =
    "node ./scripts/forward-oos-observability-dashboard-v1-static-verify.cjs";

  pkg.scripts[
    "test:forward-oos-observability-dashboard"
  ] =
    "tsx --env-file=.env.local ./scripts/forward-oos-observability-dashboard-v1-contract-test.ts";

  fs.writeFileSync(
    packageFile,
    JSON.stringify(
      pkg,
      null,
      2,
    ) + "\n",
    "utf8",
  );

  const installedHome =
    fs.readFileSync(
      home,
      "utf8",
    );

  const checks = {
    serviceInstalled:
      fs.existsSync(
        path.join(
          ROOT,
          "lib/research/get-forward-oos-observability-dashboard-v1.ts",
        ),
      ),

    apiInstalled:
      fs.existsSync(
        path.join(
          ROOT,
          "app/api/forward-oos/observability/route.ts",
        ),
      ),

    pageInstalled:
      fs.existsSync(
        path.join(
          ROOT,
          "app/forward-oos/page.tsx",
        ),
      ),

    sidebarLinkInstalled:
      installedHome.includes(
        navMarker,
      ) &&
      installedHome.includes(
        'href="/forward-oos"',
      ),

    alphaChanged:
      false,

    producerChanged:
      false,

    collectorChanged:
      false,

    forwardDatasetChanged:
      false,
  };

  const failed =
    Object.entries(
      checks,
    )
      .filter(
        ([
          key,
          value,
        ]) =>
          ![
            "alphaChanged",
            "producerChanged",
            "collectorChanged",
            "forwardDatasetChanged",
          ].includes(
            key,
          ) &&
          value !== true,
      )
      .map(
        ([key]) =>
          key,
      );

  console.log(
    JSON.stringify(
      {
        status:
          failed.length === 0
            ? "AI_STOCK_LAB_FORWARD_OOS_OBSERVABILITY_DASHBOARD_V1_INSTALLED"
            : "AI_STOCK_LAB_FORWARD_OOS_OBSERVABILITY_DASHBOARD_V1_INSTALL_FAILED",

        changedFiles: [
          "app/page.tsx",
        ],

        generatedFiles: [
          "lib/research/get-forward-oos-observability-dashboard-v1.ts",
          "app/api/forward-oos/observability/route.ts",
          "app/forward-oos/page.tsx",
          "scripts/forward-oos-observability-dashboard-v1-contract-test.ts",
          "scripts/forward-oos-observability-dashboard-v1-static-verify.cjs",
        ],

        route:
          "/forward-oos",

        api:
          "/api/forward-oos/observability",

        mode:
          "READ_ONLY_LOG_FILE_DASHBOARD",

        checks,

        safety: {
          installerExecutedProducer:
            false,

          installerExecutedCollector:
            false,

          databaseReads:
            0,

          databaseWrites:
            0,

          ordersCreated:
            0,

          positionsChanged:
            0,

          promotionExecuted:
            false,

          realTradingEnabled:
            false,
        },

        failed,

        nextAction:
          failed.length === 0
            ? "RUN_STATIC_CONTRACT_AND_NEXT_BUILD"
            : "INSPECT_DASHBOARD_INSTALL",
      },
      null,
      2,
    ),
  );

  process.exitCode =
    failed.length === 0
      ? 0
      : 1;
}
